[CmdletBinding()]
param([switch]$SkipRootMigration,[switch]$SkipManifest)

$ErrorActionPreference='Stop'
Set-StrictMode -Version Latest
$utf8=New-Object Text.UTF8Encoding($false)
$utf8Strict=New-Object Text.UTF8Encoding($false,$true)
$script:passed=0
$selfPath=$MyInvocation.MyCommand.Path

function Assert-True([bool]$Condition,[string]$Name){if(-not $Condition){throw "ASSERT_FAIL|$Name"};$script:passed++;Write-Output "PASS|$Name"}
function Write-Utf8([string]$Path,[string]$Text){$parent=Split-Path -Parent $Path;if($parent -and -not (Test-Path -LiteralPath $parent)){New-Item -ItemType Directory -Path $parent -Force|Out-Null};$value=$Text.Replace("`r`n","`n").Replace("`r","`n");if(-not $value.EndsWith("`n")){$value+="`n"};[IO.File]::WriteAllText($Path,$value,$utf8)}
function Get-Identity([string]$Path){$bytes=[IO.File]::ReadAllBytes($Path);$sha=[Security.Cryptography.SHA256]::Create();try{return $bytes.Length.ToString()+'|'+([BitConverter]::ToString($sha.ComputeHash($bytes))).Replace('-','')}finally{$sha.Dispose()}}
function Invoke-Ps([string]$Script,[string[]]$Arguments,[string]$WorkingDirectory=''){
    if($WorkingDirectory){Push-Location $WorkingDirectory}
    try{$old=$ErrorActionPreference;$ErrorActionPreference='Continue';$output=@(& powershell.exe -NoProfile -ExecutionPolicy Bypass -File $Script @Arguments 2>&1|ForEach-Object{[string]$_});$code=$LASTEXITCODE;$ErrorActionPreference=$old;return [pscustomobject]@{Code=$code;Output=$output;Text=($output-join"`n")}}
    finally{if($WorkingDirectory){Pop-Location}}
}
function New-GitRepo([string]$Path){New-Item -ItemType Directory -Path $Path -Force|Out-Null;&git -C $Path init -q;if($LASTEXITCODE-ne 0){throw'git init failed'};&git -C $Path config user.email test@example.invalid;&git -C $Path config user.name FrameworkTest}
function New-IsolatedWorkspace([string]$Root,[string]$CandidateRoot){
    $ws=Join-Path $Root 'workspace';New-Item -ItemType Directory -Path (Join-Path $ws 'framework\versions') -Force|Out-Null
    foreach($v in @('1.4.1','1.5.0','1.5.1','1.5.2')){Copy-Item -LiteralPath (Join-Path $frameworkRoot "versions\$v") -Destination (Join-Path $ws "framework\versions\$v") -Recurse}
    Copy-Item -LiteralPath $CandidateRoot -Destination (Join-Path $ws 'framework\versions\1.6.0') -Recurse
    Write-Utf8 (Join-Path $ws 'framework\CURRENT') '1.4.1'
    return $ws
}
function New-Migration([string]$Repo,[string]$ProjectId,$Paths){$path=Join-Path $Repo '.tmp\routine-exclusions.json';$obj=[ordered]@{schemaVersion=1;projectId=$ProjectId;routineExcludedPaths=@($Paths)};Write-Utf8 $path ($obj|ConvertTo-Json -Depth 20);return [pscustomobject]@{Path=$path;Identity=Get-Identity $path}}
function New-TransactionFixture([string]$Root,$Saved){$transactionId=[Guid]::NewGuid().ToString('N');New-Item -ItemType Directory -Path (Join-Path $Root 'old'),(Join-Path $Root 'new') -Force|Out-Null;Write-Utf8 (Join-Path $Root 'old\project.json') $Saved.OldProject;Write-Utf8 (Join-Path $Root 'old\BOOTSTRAP.md') $Saved.OldBootstrap;Write-Utf8 (Join-Path $Root 'new\project.json') $Saved.NewProject;Write-Utf8 (Join-Path $Root 'new\BOOTSTRAP.md') $Saved.NewBootstrap;Write-Utf8 (Join-Path $Root 'new\controller.json') $Saved.NewController;$state=[ordered]@{schemaVersion=1;transactionId=$transactionId;projectId=$Saved.Id;fromVersion='1.5.2';toVersion='1.6.0';controllerMode='CREATE';oldProjectIdentity=Get-Identity (Join-Path $Root 'old\project.json');oldBootstrapIdentity=Get-Identity (Join-Path $Root 'old\BOOTSTRAP.md');newProjectIdentity=Get-Identity (Join-Path $Root 'new\project.json');newBootstrapIdentity=Get-Identity (Join-Path $Root 'new\BOOTSTRAP.md');newControllerIdentity=Get-Identity (Join-Path $Root 'new\controller.json')};Write-Utf8 (Join-Path $Root 'state.json') ($state|ConvertTo-Json -Depth 10);return $state}
function Register-Project([string]$Script,[string]$Ws,[string]$Repo,[string]$Id,[string]$Version,[string]$Controller=''){$args=@('-ProjectId',$Id,'-DisplayName',$Id,'-RepositoryPath',$Repo,'-WorkspaceRoot',$Ws,'-Apply');if($Version){$args+=@('-FrameworkVersion',$Version)};if($Controller){$args+=@('-ControllerId',$Controller)};return Invoke-Ps $Script $args}

