        $config.routineExcludedPaths=@('scope/excluded.txt');Write-Utf8 $configPath ($config|ConvertTo-Json -Depth 20);$identity=Get-Identity $configPath;$oldGitIndex=[Environment]::GetEnvironmentVariable('GIT_INDEX_FILE','Process');try{[Environment]::SetEnvironmentVariable('GIT_INDEX_FILE',$routineRepo,'Process');$failedGit=Invoke-Ps $safeGit @('-ProjectRoot',$routineRepo,'-Operation','INDEX','-AllowPath','scope/public.txt','-ExpectedProjectConfigIdentity',$identity)}finally{[Environment]::SetEnvironmentVariable('GIT_INDEX_FILE',$oldGitIndex,'Process')};Assert-True ($failedGit.Code-ne0-and$failedGit.Text.Contains('GIT_COMMAND_FAILED')-and$failedGit.Text.Contains('"launched":true')) 'routine-git-command-failure-honest-unverified'

        $structuralRepo=Join-Path $temp 'structural-routine-data';New-GitRepo $structuralRepo;$r=Register-Project $register $ws $structuralRepo 'structural-routine-data' '1.5.2' '';$structuralMigration=New-Migration $structuralRepo 'structural-routine-data' @('../outside');$structuralArgs=@('-ProjectId','structural-routine-data','-RepositoryPath',$structuralRepo,'-ToVersion','1.6.0','-ControllerId','controller-structural','-RoutineExcludedPathsMigrationPath',$structuralMigration.Path,'-ExpectedRoutineExcludedPathsMigrationIdentity',$structuralMigration.Identity,'-WorkspaceRoot',$ws,'-Apply');$structuralApply=Invoke-Ps $upgrade $structuralArgs;$structuralRepeat=Invoke-Ps $upgrade $structuralArgs;$structuralConfigPath=Join-Path $structuralRepo '.ai-workspace\project.json';$structuralConfig=Get-Content -LiteralPath $structuralConfigPath -Raw|ConvertFrom-Json;Assert-True ($r.Code-eq0-and$structuralApply.Code-eq0-and$structuralRepeat.Code-eq0-and$structuralRepeat.Text.Contains('ALREADY_UPGRADED')-and[string]$structuralConfig.routineExcludedPaths[0]-ceq'../outside') 'routine-exclusions-structural-producer-and-repeat-health'
        $structuralUse=Invoke-Ps $safeGit @('-ProjectRoot',$structuralRepo,'-Operation','STATUS','-AllowPath','public.txt','-ExpectedProjectConfigIdentity',(Get-Identity $structuralConfigPath));Assert-True ($structuralUse.Code-ne0-and$structuralUse.Text.Contains('UNVERIFIED')) 'routine-exclusion-structural-data-rejected-at-use-site'

        $knowledgeUpgradeRepo=Join-Path $temp 'knowledge-upgrade';New-GitRepo $knowledgeUpgradeRepo;$r=Register-Project $register $ws $knowledgeUpgradeRepo 'knowledge-upgrade' '1.5.2' '';$knowledgeMigration=New-Migration $knowledgeUpgradeRepo 'knowledge-upgrade' @();$knowledgeUpgradeArgs=@('-ProjectId','knowledge-upgrade','-RepositoryPath',$knowledgeUpgradeRepo,'-ToVersion','1.6.0','-ControllerId','controller-knowledge','-RoutineExcludedPathsMigrationPath',$knowledgeMigration.Path,'-ExpectedRoutineExcludedPathsMigrationIdentity',$knowledgeMigration.Identity,'-WorkspaceRoot',$ws,'-Apply');$knowledgeApply=Invoke-Ps $upgrade $knowledgeUpgradeArgs;$knowledgeConfigPath=Join-Path $knowledgeUpgradeRepo '.ai-workspace\project.json';$knowledgeConfig=Get-Content -LiteralPath $knowledgeConfigPath -Raw|ConvertFrom-Json;$knowledgeConfig.frameworkCapabilities=[pscustomobject]@{KNOWLEDGE_REFERENCE=[pscustomobject]@{enabled=$true;indexLocator='.ai-workspace/knowledge/index.json'}};Write-Utf8 $knowledgeConfigPath ($knowledgeConfig|ConvertTo-Json -Depth 20);$knowledgeRepeat=Invoke-Ps $upgrade $knowledgeUpgradeArgs;Assert-True ($r.Code-eq0-and$knowledgeApply.Code-eq0-and$knowledgeRepeat.Code-eq0-and$knowledgeRepeat.Text.Contains('ALREADY_UPGRADED')) 'upgrade-repeat-accepts-valid-knowledge-capability'

        $driftRepo=Join-Path $temp 'migration-drift';New-GitRepo $driftRepo;$r=Register-Project $register $ws $driftRepo 'migration-drift' '1.5.2' '';$migration=New-Migration $driftRepo 'migration-drift' @();Write-Utf8 $migration.Path ((Get-Content -LiteralPath $migration.Path -Raw)+' ');$drift=Invoke-Ps $upgrade @('-ProjectId','migration-drift','-RepositoryPath',$driftRepo,'-ToVersion','1.6.0','-ControllerId','controller-drift','-RoutineExcludedPathsMigrationPath',$migration.Path,'-ExpectedRoutineExcludedPathsMigrationIdentity',$migration.Identity,'-WorkspaceRoot',$ws,'-Apply');Assert-True ($drift.Code-ne0-and-not(Test-Path -LiteralPath (Join-Path $driftRepo '.ai-workspace\controller.json'))) 'upgrade-migration-drift-no-write'
    }

    $forbidden=@('check-controller-route','check-remote-batch','resolve-resource-binding','controller-revocations','check-peer-task-reuse','PreviousLedger','COMPENSATION')
    $activeCode=@(Get-ChildItem -LiteralPath (Join-Path $candidateRoot 'scripts') -Recurse -File -Include *.ps1,*.json);$activeCode+=@(Get-Item -LiteralPath (Join-Path $rootDraft 'scripts\register-project.ps1'),(Join-Path $rootDraft 'scripts\upgrade-project.ps1'))
    foreach($term in $forbidden){$hits=@($activeCode|Select-String -Pattern $term -SimpleMatch);Assert-True ($hits.Count-eq0) ("old-mechanism-zero-code|"+$term)}
    $allText=@(Get-ChildItem -LiteralPath $candidateRoot -Recurse -File|Where-Object{$_.FullName-cne$selfPath}|ForEach-Object{Get-Content -LiteralPath $_.FullName -Raw -Encoding utf8});$allText+=@($rootExpected|ForEach-Object{Get-Content -LiteralPath (Join-Path $rootDraft $_) -Raw -Encoding utf8});$allText=$allText-join"`n"
    Assert-True (-not$allText.Contains('lean-candidate/')-and-not$allText.Contains('candidate/')-and-not$allText.Contains('lean-root-scripts/')-and-not$allText.Contains('root-scripts/')) 'old-tree-zero-import-path'

    if(-not$SkipManifest){
        $manifest=Get-Content -LiteralPath (Join-Path $candidateRoot 'RELEASE_MANIFEST.json') -Raw|ConvertFrom-Json
        [string[]]$payload=@($actual|Where-Object{$_-cne'RELEASE_MANIFEST.json'});[Array]::Sort($payload,[StringComparer]::Ordinal)
        $rows=@();$total=[int64]0;foreach($path in $payload){$full=Join-Path $candidateRoot $path;$bytes=[IO.File]::ReadAllBytes($full);$total+=$bytes.Length;$rows+=("$path|$($bytes.Length)|"+(Get-Identity $full).Split('|')[1])}
        $canonicalBytes=$utf8.GetBytes(($rows-join"`n"));$sha=[Security.Cryptography.SHA256]::Create();try{$canonical=([BitConverter]::ToString($sha.ComputeHash($canonicalBytes))).Replace('-','')}finally{$sha.Dispose()}
        Assert-True ([int]$manifest.fileCount-eq$payload.Count-and[int64]$manifest.totalBytes-eq$total-and[string]$manifest.canonical-ceq$canonical) 'release-manifest-canonical'
    }
}
finally{
    if(Test-Path -LiteralPath $temp){Get-ChildItem -LiteralPath $temp -Recurse -Force -ErrorAction SilentlyContinue|ForEach-Object{try{$_.Attributes=[IO.FileAttributes]::Normal}catch{}};Remove-Item -LiteralPath $temp -Recurse -Force -ErrorAction SilentlyContinue}
}

Write-Output ("RESULT|"+$script:passed+"/"+$script:passed+" passed|scope=Framework-1.6.0-stable|lifecycle=STABLE")
